<section class="mt-5 rounded-xl border border-line bg-white p-5" aria-label="Delivery history">
    <h3 class="break-all font-semibold">{{ $delivery->reference }}</h3>
    <p class="mt-2 text-sm"><strong>{{ $delivery->label() }}</strong> / {{ $delivery->recipient_snapshot['name'] }} / {{ $delivery->recipient_snapshot['email'] }}</p>
    @if($delivery->status === 'accepted')<p role="status" class="mt-3 text-sm font-semibold text-moss">Referral email sent successfully. SMTP accepted the message; inbox receipt {{ $delivery->inbox_confirmed_at ? 'was separately confirmed by an administrator' : 'is not yet confirmed' }}.</p>@endif
    @if(!$delivery->pollution_report_id)<p class="mt-3 text-sm text-muted">Preserved legacy diagnostic record. Sending is disabled; existing queue records are retained.</p>
    @elseif($delivery->status === 'queued' && !$delivery->deliveryApproved())<p class="mt-3 text-sm">This legacy approval is paused. Review its preserved snapshot and confirm Send to Municipality before delivery. The old queued job stays intact.</p>@endif
    @if($delivery->error_code)<p role="alert" class="mt-3 text-sm">{{ match($delivery->error_code) { 'smtp_auth_rejected' => 'Gmail rejected sender authentication. Update the sender App Password locally, clear configuration and restart the worker, then retry.', 'smtp_connection_failed' => 'SMTP connection or TLS failed before submission. Check host, port and TLS settings locally, restart the worker and retry.', 'worker_interrupted' => $delivery->sending_at ? 'Worker stopped after submission began. Check the inbox before any resend.' : 'Worker stopped before SMTP submission. Restart it and retry safely.', 'smtp_rejected' => 'SMTP rejected this message. Check receiver and provider settings, then retry.', 'preflight_failed' => 'Delivery preparation failed. Check SMTP configuration and the approved private attachment before retrying.', default => 'The delivery outcome is uncertain. Check the receiver inbox and provider records before any further action.' } }}</p>@endif
    <p class="mt-3 text-xs">Delivery attempts: {{ $delivery->attempts }}. Approved {{ $delivery->approved_at?->toIso8601String() }}. Queued {{ $delivery->queued_at?->toIso8601String() }}. SMTP accepted {{ $delivery->sent_at?->toIso8601String() ?: 'Not recorded' }}.</p>
    <details class="mt-4 text-sm"><summary>Approval snapshot and delivery events</summary><pre class="mt-3 whitespace-pre-wrap break-words font-sans text-xs">@include('mail.referral-text', ['details'=>$delivery->payload,'reference'=>$delivery->reference])</pre><ol class="mt-3 space-y-2">@foreach($delivery->events as $event)<li>{{ $event->created_at->toIso8601String() }} / {{ $event->event }}</li>@endforeach</ol></details>
    @if(($allowActions ?? false) && $delivery->retryable())
        <form method="POST" action="{{ route('admin.referrals.retry', [$report, $delivery]) }}" data-confirm-send="Retry this confirmed unsent message to {{ $delivery->recipient_snapshot['email'] }}?" class="mt-4 space-y-3">@csrf<label class="flex gap-3 text-sm"><input type="checkbox" name="approved" value="1" required><span>I corrected the failure and approve retrying this preserved message.</span></label><button class="secondary-button">Retry safely</button></form>
    @endif
    @if(($allowActions ?? false) && $delivery->status === 'accepted' && !$delivery->inbox_confirmed_at)
        <form method="POST" action="{{ route('admin.referrals.confirm', [$report, $delivery]) }}" class="mt-4 space-y-3">@csrf<label class="form-label" for="confirmation_reference">Reference found in receiver inbox</label><input class="form-input" id="confirmation_reference" name="confirmation_reference" required autocomplete="off"><label class="flex gap-3 text-sm"><input type="checkbox" name="approved" value="1" required><span>I personally found this exact reference in the receiver inbox.</span></label><button class="secondary-button">Confirm receiver inbox receipt</button></form>
    @endif
</section>
